 @AfterEach void cleanup(){if(admin!=null&&schema!=null)admin.execute("drop schema "+schema+" cascade");}
 Map<String,Object> input(long qty,String request){var d=new LinkedHashMap<String,Object>();d.putAll(Map.of("sourceType","partner","specId",15L,"supplierCode","SUP-A","qty",qty,"date",java.time.LocalDate.now().toString(),"location","中国工程柜","ownerName","QA工程","requestId",request));return d;}
 Map<String,Object> receive(long qty,String request){return tx.execute(t->samples.create(input(qty,request)));}
 long count(String kind){return jdbc.queryForObject("select count(*) from plm_partner_record where kind=?",Long.class,kind);}
 @Test void catalogRenameUpdatesSyAndSpDisplayAndSearchWithoutRewritingReceiptFacts(){
  String rid=UUID.randomUUID().toString();long origin=jdbc.queryForObject("insert into plm_partner_record(kind,code,name,status,version,owner_user_id,data) values('selection','SL-CURRENT','供应商原目录','draft',2,1,'{\"catalogSource\":true}') returning record_id",Long.class);
  jdbc.update("insert into plm_partner_selection_row values(?,?::uuid,2,1,?::jsonb,false)",origin,rid,encode(store.json,Map.of("name","凡影精孔手机壳","supplierCode","SUP-A","color","蓝色","material","PC","unitPrice","3.80","currency","CNY")));
  jdbc.update("insert into plm_partner_catalog_style_source(style_id,record_id,source_kind,row_id) values(13,?,'selection',?::uuid)",origin,rid);
  var source=new LinkedHashMap<String,Object>(Map.of("sourceType","catalog","catalogStyleId",13L,"phoneModelId",12L,"colorId",10L,"colorName","黑色","catalogConfigurationKey","original","name","凡影大孔手机壳"));
  var identity=tx.execute(t->registry.ensure(source,Map.of("requestId","catalog-current")));long id=number(identity.get("id"));
  var batch=new LinkedHashMap<>(source);batch.put("status","active");batch.put("sourceSnapshot",Map.of("name","凡影大孔手机壳","color","黑色","sourceRecordId",origin,"sourceRowId",rid));
  long sp=jdbc.queryForObject("insert into plm_partner_record(kind,code,name,status,version,owner_user_id,sample_identity_id,data) values('sample','SP-CURRENT','凡影大孔手机壳','active',1,1,?,?::jsonb) returning record_id",Long.class,id,encode(store.json,batch));
  jdbc.update("insert into plm_partner_event(record_id,action,data,request_id,created_by,actor_id) values(?,'receive','{\"qty\":2,\"date\":\"2026-10-01\",\"location\":\"mx\",\"condition\":\"good\"}','catalog-current-receive','工程',1)",sp);
  String before=jdbc.queryForObject("select jsonb_agg(to_jsonb(r) order by record_id)::text from plm_partner_record r where record_id in (?,?)",String.class,id,sp);
  var current=registry.detail(id);assertThat(current).containsEntry("name","凡影精孔手机壳").containsEntry("productName","凡影精孔手机壳").containsEntry("recordedName","凡影大孔手机壳").containsEntry("colorName","黑色");
  assertThat(map(current.get("balances"))).containsEntry("onhand",2L);assertThat(map(maps(current.get("batches")).get(0).get("sourceSnapshot"))).containsEntry("name","凡影大孔手机壳").containsEntry("color","黑色");
  assertThat(maps(registry.page(Map.of("keyword","凡影精孔","size","1")).get("content"))).hasSize(1).first().satisfies(row->assertThat(row).containsEntry("code",identity.get("code")));
  assertThat(samples.detail(sp)).containsEntry("name","凡影精孔手机壳").containsEntry("colorName","黑色");
  assertThat(jdbc.queryForObject("select jsonb_agg(to_jsonb(r) order by record_id)::text from plm_partner_record r where record_id in (?,?)",String.class,id,sp)).isEqualTo(before);
  restricted=true;user=2;allowed.add(sp);assertThat(registry.detail(id)).containsEntry("name","凡影大孔手机壳").doesNotContainKey("currentCatalog");
 }
 @Test void samePhysicalTypeReceivedThreeThenTwoHasOneCodeTwoSpLedgersAndFiveUnits(){var first=receive(3,"first");var second=receive(2,"second");assertThat(first.get("sampleCode")).isEqualTo(second.get("sampleCode"));assertThat(first.get("id")).isNotEqualTo(second.get("id"));var detail=registry.detail(number(first.get("sampleIdentityId")));assertThat(number(map(detail.get("balances")).get("onhand"))).isEqualTo(5);assertThat(maps(detail.get("batches"))).hasSize(2);assertThat(count("sample_identity")).isEqualTo(1);long events=jdbc.queryForObject("select count(*) from plm_partner_event",Long.class);for(int i=0;i<5;i++)registry.detail(number(detail.get("id")));assertThat(jdbc.queryForObject("select count(*) from plm_partner_event",Long.class)).isEqualTo(events);assertThat(count("sample")).isEqualTo(3);}
 @Test void receiptRetryReturnsOriginalBatchButDifferentBodyIsRejected(){var one=receive(3,"retry");assertThat(receive(3,"retry").get("id")).isEqualTo(one.get("id"));assertThatThrownBy(()->receive(2,"retry")).hasMessageContaining("内容不同");assertThat(count("sample_identity")).isEqualTo(1);assertThat(count("sample")).isEqualTo(2);}
 @Test void concurrentSameTypeNeverCreatesDuplicateMasterOrLosesQuantity()throws Exception{var ready=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{ready.await();return receive(3,"concurrent-a");});var b=pool.submit(()->{ready.await();return receive(2,"concurrent-b");});ready.countDown();var first=a.get(15,TimeUnit.SECONDS);var second=b.get(15,TimeUnit.SECONDS);assertThat(first.get("sampleCode")).isEqualTo(second.get("sampleCode"));assertThat(count("sample_identity")).isEqualTo(1);assertThat(number(map(registry.detail(number(first.get("sampleIdentityId"))).get("balances")).get("onhand"))).isEqualTo(5);}finally{pool.shutdownNow();}}
 @Test void aggregateLoanAllocatesOriginalBatchesAndRequestBodyCannotBeReused(){var first=receive(3,"loan-a");receive(2,"loan-b");long identity=number(first.get("sampleIdentityId"));var head=registry.detail(identity);var command=new LinkedHashMap<String,Object>(Map.of("version",head.get("version"),"requestId","loan-four","qty",4L,"date",java.time.LocalDate.now().toString(),"location","中国工程柜","person","QA借用人","due",java.time.LocalDate.now().plusDays(1).toString()));var moved=tx.execute(t->actions.action(identity,"loan",command));assertThat(number(map(moved.get("balances")).get("onhand"))).isEqualTo(1);assertThat(number(map(moved.get("balances")).get("borrowed"))).isEqualTo(4);assertThat(maps(moved.get("loans"))).hasSize(2);tx.execute(t->actions.action(identity,"loan",command));command.put("qty",3);assertThatThrownBy(()->tx.execute(t->actions.action(identity,"loan",command))).hasMessageContaining("不同样品动作");}
 @Test void legacyBindingChangesOnlyFkAndMainCodeAuditNotOldJsonEventsOrStock(){var fresh=receive(1,"legacy-master");long identity=number(fresh.get("sampleIdentityId"));var before=jdbc.queryForMap("select code,data::text,version from plm_partner_record where record_id=1");String events=jdbc.queryForObject("select coalesce(jsonb_agg(to_jsonb(e))::text,'[]') from plm_partner_event e where record_id=1",String.class);var input=new LinkedHashMap<String,Object>(Map.of("version",0L,"requestId","link-old","sampleIdentityId",identity,"identityReason","现场核对为同种实物"));tx.execute(t->actions.bind(1,input));assertThat(jdbc.queryForMap("select code,data::text,version from plm_partner_record where record_id=1")).isEqualTo(before);assertThat(jdbc.queryForObject("select coalesce(jsonb_agg(to_jsonb(e))::text,'[]') from plm_partner_event e where record_id=1",String.class)).isEqualTo(events);assertThat(number(map(registry.detail(identity).get("balances")).get("onhand"))).isEqualTo(10);assertThat(number(map(registry.detail(identity).get("balances")).get("borrowed"))).isEqualTo(1);assertThat(registry.resolve("SP-000001")).containsEntry("sampleIdentityId",identity);}
 @Test void typeAggregationIncludesOnlyVisibleSpNotAllBatchesWithTheSameCode(){var a=receive(3,"acl-a");receive(2,"acl-b");long identity=number(a.get("sampleIdentityId"));restricted=true;user=2;allowed.add(number(a.get("id")));var detail=registry.detail(identity);assertThat(number(map(detail.get("balances")).get("onhand"))).isEqualTo(3);assertThat(maps(detail.get("batches"))).hasSize(1);assertThat(detail.toString()).doesNotContain("acl-b");}
 @Test void failedActualQuantityRollsBackMasterAndAllReceiptFacts(){assertThatThrownBy(()->receive(0,"invalid-qty")).hasMessageContaining("数量");assertThat(count("sample_identity")).isZero();assertThat(count("sample")).isEqualTo(1);}
 @Test void directIdentityRequestRejectsChangedInputAndNeverCreatesStock(){var source=Map.<String,Object>of("sourceType","catalog","catalogStyleId",1L,"phoneModelId",12L,"colorId",3L,"catalogConfigurationKey","A","name","真实类型");var command=new LinkedHashMap<String,Object>(Map.of("requestId","identity-only"));var head=tx.execute(t->registry.ensure(source,command));assertThat(tx.execute(t->registry.ensure(source,command)).get("id")).isEqualTo(head.get("id"));command.put("unrelated",true);assertThatThrownBy(()->tx.execute(t->registry.ensure(source,command))).hasMessageContaining("不同样品身份来源");assertThat(count("sample")).isEqualTo(1);assertThat(map(registry.detail(number(head.get("id"))).get("balances"))).containsEntry("onhand",0L);} Map<String,Object> pending(long qty,String request){var input=input(qty,request);input.put("pending",true);input.put("name","待核实实物");input.put("provenance","旧样品实际盘点，来源待补");return tx.execute(t->samples.create(input));}
 Map<String,Object> resolveInput(Map<String,Object> batch,String request){var command=input(1,request);command.put("pending",false);command.put("version",batch.get("version"));command.put("reason","现场补齐真实供方和规格");return command;}
 @Test void resolvingPendingSourceKeepsItsOriginalCodeAndFutureReceiptsReuseIt(){var unknown=pending(3,"pending-origin");long batch=number(unknown.get("id")),identity=number(unknown.get("sampleIdentityId"));String code=text(unknown.get("sampleCode"));var command=resolveInput(unknown,"resolve-origin");tx.execute(t->samples.action(batch,"source_resolve",command));var later=receive(2,"same-after-resolve");assertThat(later.get("sampleIdentityId")).isEqualTo(identity);assertThat(later.get("sampleCode")).isEqualTo(code);assertThat(number(map(registry.detail(identity).get("balances")).get("onhand"))).isEqualTo(5);assertThat(count("sample_identity")).isEqualTo(1);}
 @Test void pendingCanonicalConflictRequiresExplicitSameTypeConfirmationAndOldCodeRedirects(){var canonical=receive(3,"canonical");var unknown=pending(2,"unknown-conflict");long target=number(canonical.get("sampleIdentityId")),old=number(unknown.get("sampleIdentityId")),batch=number(unknown.get("id"));var command=resolveInput(unknown,"resolve-conflict");String before=jdbc.queryForObject("select data::text from plm_partner_record where record_id=?",String.class,batch);assertThatThrownBy(()->tx.execute(t->samples.action(batch,"source_resolve",command))).hasMessageContaining("不能自动合并");assertThat(jdbc.queryForObject("select data::text from plm_partner_record where record_id=?",String.class,batch)).isEqualTo(before);command.put("mergeTargetIdentityId",target);command.put("confirmSameType",true);command.put("identityReason","工程现场逐项核实同一实际规格");tx.execute(t->samples.action(batch,"source_resolve",command));var resolved=registry.resolve(text(unknown.get("sampleCode")));assertThat(map(resolved.get("identity")).get("id")).isEqualTo(target);assertThat(number(map(registry.detail(target).get("balances")).get("onhand"))).isEqualTo(5);assertThat(registry.detail(old)).containsEntry("legacySampleCode",unknown.get("sampleCode"));assertThat(count("sample")).isEqualTo(3);}
 @Test void sourceResolutionAndAggregateMovementHaveAConsistentLockOrder()throws Exception{var unknown=pending(3,"lock-order");long identity=number(unknown.get("sampleIdentityId")),batch=number(unknown.get("id"));var ready=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var source=pool.submit(()->{ready.await();return tx.execute(t->samples.action(batch,"source_resolve",resolveInput(unknown,"resolve-parallel")));});var move=pool.submit(()->{ready.await();var h=registry.detail(identity);return tx.execute(t->actions.action(identity,"move",Map.of("version",h.get("version"),"requestId","move-parallel","qty",1,"date",java.time.LocalDate.now().toString(),"location","中国工程柜","to","墨西哥接收处")));});ready.countDown();try{source.get(10,TimeUnit.SECONDS);}catch(ExecutionException e){assertThat(e.getCause()).hasMessageContaining("记录已变化");}try{move.get(10,TimeUnit.SECONDS);}catch(ExecutionException e){assertThat(e.getCause()).hasMessageContaining("记录已变化");}assertThat(number(map(registry.detail(identity).get("balances")).get("onhand"))).isEqualTo(3);}finally{pool.shutdownNow();}}
 @Test void legacyBindingAndBorrowingNeverTakeSpBeforeTheTypeHead()throws Exception{var fresh=receive(3,"bind-concurrent-master");long identity=number(fresh.get("sampleIdentityId"));var ready=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var bind=pool.submit(()->{ready.await();return tx.execute(t->actions.bind(1,new LinkedHashMap<>(Map.of("version",0L,"sampleIdentityId",identity,"requestId","concurrent-bind","identityReason","历史实物同种核对"))));});var loan=pool.submit(()->{ready.await();var h=registry.detail(identity);return tx.execute(t->actions.action(identity,"loan",Map.of("version",h.get("version"),"requestId","concurrent-loan","qty",1,"date",java.time.LocalDate.now().toString(),"location","中国工程柜","person","并发借用","due",java.time.LocalDate.now().plusDays(1).toString())));});ready.countDown();bind.get(10,TimeUnit.SECONDS);try{loan.get(10,TimeUnit.SECONDS);}catch(ExecutionException e){assertThat(e.getCause()).hasMessageContaining("记录已变化");}assertThat(count("sample_identity")).isEqualTo(1);assertThat(number(map(registry.detail(identity).get("balances")).get("onhand"))).isBetween(11L,12L);}finally{pool.shutdownNow();}}
 @Test void reusingAConfigurationIdWithChangedKnownMaterialIsRejectedWithoutAddingStock(){var first=new LinkedHashMap<String,Object>(Map.of("sourceType","catalog","catalogStyleId",7L,"phoneModelId",12L,"colorId",3L,"catalogConfigurationKey","same-source-config","name","真实类型","sourceSnapshot",Map.of("material","PC","configuration","支架A")));var original=tx.execute(t->registry.ensure(first,Map.of("requestId","material-first")));var changed=new LinkedHashMap<>(first);changed.put("sourceSnapshot",Map.of("material","TPU","configuration","支架A"));assertThatThrownBy(()->tx.execute(t->registry.ensure(changed,Map.of("requestId","material-change")))).hasMessageContaining("材料");assertThat(count("sample_identity")).isEqualTo(1);assertThat(count("sample")).isEqualTo(1);assertThat(map(registry.detail(number(original.get("id"))).get("balances"))).containsEntry("onhand",0L);}
 @Test void anAuthorizedModelProductSourceCanSeeAZeroStockTypeWithoutSeeingOtherPeoplesBatches(){var source=Map.<String,Object>of("sourceType","model","modelProductId",7L,"phoneModelId",12L,"sampleVersion","V1","name","实际产品型号样品");var head=tx.execute(t->registry.ensure(source,Map.of("requestId","zero-stock-model")));restricted=true;user=2;allowedProducts.add(7L);var visible=registry.detail(number(head.get("id")));assertThat(visible.get("code")).isEqualTo(head.get("code"));assertThat(maps(visible.get("batches"))).isEmpty();assertThat(map(visible.get("balances"))).containsEntry("onhand",0L);allowedProducts.clear();assertThatThrownBy(()->registry.detail(number(head.get("id")))).hasMessageContaining("未获授权");}
 @Test void supplierLabelUsesTheActualReceiptSourceAndNeverAProjectCurrentVendor(){var batch=receive(2,"supplier-label");assertThat(batch).containsEntry("supplierCode","SUP-A").containsEntry("supplierName","实际原供方");var type=registry.detail(number(batch.get("sampleIdentityId")));assertThat(type).containsEntry("supplierCode","SUP-A").containsEntry("supplierName","实际原供方");var unknown=Map.<String,Object>of("sourceType","model","modelProductId",7L,"phoneModelId",12L,"sampleVersion","V1","name","未明确供方的自有样品");var empty=tx.execute(t->registry.ensure(unknown,Map.of("requestId","unknown-supplier")));assertThat(empty).containsEntry("supplierName","").containsEntry("supplierCode","");}


 Map<String,Object> bulkItem(Map<String,Object> b,long qty){long identity=number(b.get("sampleIdentityId"));return new LinkedHashMap<>(Map.of("sampleIdentityId",identity,"version",registry.detail(identity).get("version"),"qty",qty,"location","中国工程柜"));}
 @Test void bulkLoansAndReturnsAreAtomicAcrossTypesAndRetryDoesNotRepeatFacts(){
  var a=receive(3,"bulk-first");var otherInput=input(4,"bulk-second");otherInput.put("sampleVersion","V2");var b=tx.execute(t->samples.create(otherInput));
  var command=new LinkedHashMap<String,Object>(Map.of("requestId","bulk-two","date",java.time.LocalDate.now().toString(),"person","QA接收人","due",java.time.LocalDate.now().plusDays(2).toString(),"items",List.of(bulkItem(a,2),bulkItem(b,3))));
  tx.execute(t->actions.bulk("loan",command));long events=jdbc.queryForObject("select count(*) from plm_partner_event",Long.class);tx.execute(t->actions.bulk("loan",command));assertThat(jdbc.queryForObject("select count(*) from plm_partner_event",Long.class)).isEqualTo(events);
  var returns=new ArrayList<Map<String,Object>>();for(var batch:List.of(a,b)){var h=registry.detail(number(batch.get("sampleIdentityId")));var loan=maps(h.get("loans")).get(0);returns.add(new LinkedHashMap<>(Map.of("sampleIdentityId",h.get("id"),"version",h.get("version"),"allocations",List.of(Map.of("batchId",loan.get("batchId"),"loanId",loan.get("id"),"qty",1,"damaged",0,"location","归还柜")))));}
  tx.execute(t->actions.bulk("return",Map.of("requestId","return-two","date",java.time.LocalDate.now().toString(),"items",returns)));assertThat(number(map(registry.detail(number(a.get("sampleIdentityId"))).get("balances")).get("borrowed"))).isEqualTo(1);assertThat(number(map(registry.detail(number(b.get("sampleIdentityId"))).get("balances")).get("borrowed"))).isEqualTo(2);
  command.put("person","另一个接收人");assertThatThrownBy(()->tx.execute(t->actions.bulk("loan",command))).hasMessageContaining("不同批量操作");
 }
 @Test void invalidSecondBulkLineRollsBackTheFirstAndDuplicateTypesAreRejected(){
  var a=receive(3,"atomic-a");var other=input(1,"atomic-b");other.put("sampleVersion","V2");var b=tx.execute(t->samples.create(other));long events=jdbc.queryForObject("select count(*) from plm_partner_event",Long.class);
  var command=new LinkedHashMap<String,Object>(Map.of("requestId","atomic-fail","date",java.time.LocalDate.now().toString(),"person","QA","due",java.time.LocalDate.now().plusDays(1).toString(),"items",List.of(bulkItem(a,1),bulkItem(b,2))));assertThatThrownBy(()->tx.execute(t->actions.bulk("loan",command))).hasMessageContaining("数量不足");assertThat(jdbc.queryForObject("select count(*) from plm_partner_event",Long.class)).isEqualTo(events);assertThat(number(map(registry.detail(number(a.get("sampleIdentityId"))).get("balances")).get("available"))).isEqualTo(3);
  command.put("items",List.of(bulkItem(a,1),bulkItem(a,1)));assertThatThrownBy(()->tx.execute(t->actions.bulk("loan",command))).hasMessageContaining("重复");
 }
 Map<String,Object> catalog(long color,long qty,String request){return tx.execute(t->{var source=new LinkedHashMap<String,Object>(Map.of("sourceType","catalog","catalogStyleId",71L,"supplierCode","SUP-A","phoneModelId",12L,"colorId",color,"colorName",color==10?"黑色":"紫色","catalogConfigurationKey","config-a","name","实际透明壳","sourceSnapshot",Map.of("styleKey","style-a","configKey","config-a","material","PC","configuration","实际配置")));var h=registry.ensure(source,Map.of("requestId",request));long id=store.create("sample","实际透明壳");source.put("status","active");store.save(id,source);store.event(id,"receive",Map.of("qty",qty,"date",java.time.LocalDate.now().toString(),"location","中国工程柜","condition","good","sourceSnapshot",source.get("sourceSnapshot")),request);registry.attach(id,number(h.get("id")),Map.of("identityReason","本次实收确认"));return samples.detail(id);});}
 Map<String,Object> colorCommand(long identity,String request){return new LinkedHashMap<>(Map.of("requestId",request,"version",registry.detail(identity).get("version"),"colorId",11L,"colorName","紫色","reason","实际收到紫色，原登记误填黑色"));}
 @Test void correctingColorKeepsSameCodeAndAllOriginalReceiptBorrowAndStockFacts(){
  var b=catalog(10,5,"color-receipt");long id=number(b.get("sampleIdentityId")),batch=number(b.get("id"));var h=registry.detail(id);tx.execute(t->actions.action(id,"loan",Map.of("requestId","color-loan","version",h.get("version"),"qty",2,"date",java.time.LocalDate.now().toString(),"due",java.time.LocalDate.now().plusDays(1).toString(),"person","客户","location","中国工程柜")));
  String original=jdbc.queryForObject("select data->'sourceSnapshot' from plm_partner_record where record_id=?",String.class,batch),oldEvents=jdbc.queryForObject("select jsonb_agg(to_jsonb(e) order by event_id)::text from plm_partner_event e where record_id=?",String.class,batch);var balances=map(registry.detail(id).get("balances"));var command=colorCommand(id,"color-fix");var result=tx.execute(t->actions.action(id,"correct_color",command));assertThat(result).containsEntry("code",h.get("code")).containsEntry("colorName","紫色");assertThat(number(result.get("colorId"))).isEqualTo(11);assertThat(map(result.get("balances"))).isEqualTo(balances);assertThat(jdbc.queryForObject("select data->'sourceSnapshot' from plm_partner_record where record_id=?",String.class,batch)).isEqualTo(original);assertThat(jdbc.queryForObject("select jsonb_agg(to_jsonb(e) order by event_id)::text from plm_partner_event e where record_id=? and action<>'color_correction'",String.class,batch)).isEqualTo(oldEvents);assertThat(samples.detail(batch)).containsEntry("colorName","紫色");long count=jdbc.queryForObject("select count(*) from plm_partner_event",Long.class);tx.execute(t->actions.action(id,"correct_color",command));assertThat(jdbc.queryForObject("select count(*) from plm_partner_event",Long.class)).isEqualTo(count);
 }
 @Test void existingSameColorRequiresExplicitMergeAndReleasesTheWrongOldColorKey(){
  var black=catalog(10,3,"black-wrong");var purple=catalog(11,2,"purple-real");long from=number(black.get("sampleIdentityId")),target=number(purple.get("sampleIdentityId"));var command=colorCommand(from,"merge-color");var preview=actions.previewColor(from,command);assertThat(preview).containsEntry("targetIdentityId",target).containsEntry("targetSampleCode",purple.get("sampleCode"));assertThatThrownBy(()->tx.execute(t->actions.action(from,"correct_color",command))).hasMessageContaining("不能自动合并");assertThat(number(map(registry.detail(from).get("balances")).get("onhand"))).isEqualTo(3);
  command.put("targetIdentityId",target);command.put("confirmSameType",true);var merged=tx.execute(t->actions.action(from,"correct_color",command));assertThat(merged).containsEntry("id",target).containsEntry("legacySampleCode",black.get("sampleCode"));assertThat(number(map(merged.get("balances")).get("onhand"))).isEqualTo(5);assertThat(tx.execute(t->actions.action(from,"correct_color",command)).get("id")).isEqualTo(target);var next=catalog(10,1,"actual-black-later");assertThat(next.get("sampleIdentityId")).isNotEqualTo(from).isNotEqualTo(target);assertThat(number(map(registry.detail(target).get("balances")).get("onhand"))).isEqualTo(5);
 }
 @Test void colorCorrectionRejectsWrongSupplierStaleVersionAndHiddenBatches(){
  var one=catalog(10,3,"acl-color-a");var two=catalog(10,2,"acl-color-b");long id=number(one.get("sampleIdentityId"));var wrong=colorCommand(id,"wrong-color-source");wrong.put("colorId",12);wrong.put("colorName","红色");assertThatThrownBy(()->tx.execute(t->actions.action(id,"correct_color",wrong))).hasMessageContaining("不属于");var command=colorCommand(id,"stale-color");command.put("version",0);var stale=command;assertThatThrownBy(()->tx.execute(t->actions.action(id,"correct_color",stale))).hasMessageContaining("记录已变化");restricted=true;user=2;allowed.add(number(one.get("id")));var hidden=colorCommand(id,"hidden-color");assertThatThrownBy(()->tx.execute(t->actions.action(id,"correct_color",hidden))).hasMessageContaining("未获授权的收样批次");restricted=false;assertThat(registry.detail(id)).containsEntry("colorName","黑色");
 }
 @Test void directlyTypedActualColorCreatesOneSupplierColorAndNoNewStock(){var batch=catalog(10,2,"new-color-receipt");long id=number(batch.get("sampleIdentityId"));var command=new LinkedHashMap<String,Object>(Map.of("requestId","new-color","version",registry.detail(id).get("version"),"colorName","烟紫色","reason","实物颜色录错，更正实际颜色"));var result=tx.execute(t->actions.action(id,"correct_color",command));assertThat(result).containsEntry("colorName","烟紫色");assertThat(number(map(result.get("balances")).get("onhand"))).isEqualTo(2);assertThat(jdbc.queryForObject("select count(*) from plm_supplier_color where supplier_code='SUP-A' and name='烟紫色'",Long.class)).isEqualTo(1);tx.execute(t->actions.action(id,"correct_color",command));assertThat(jdbc.queryForObject("select count(*) from plm_supplier_color where name='烟紫色'",Long.class)).isEqualTo(1);}

 @Test void correctionPreviewNeverDisclosesAnExistingColourIdentityOutsideTheReadersScope(){var wrong=catalog(10,3,"scope-wrong");var other=catalog(11,2,"scope-target");long id=number(wrong.get("sampleIdentityId"));restricted=true;user=2;allowed.add(number(wrong.get("id")));var command=colorCommand(id,"scope-preview");assertThatThrownBy(()->actions.previewColor(id,command)).hasMessageContaining("未获授权").hasMessageNotContaining(text(other.get("sampleCode")));}

